// ── set these two, then Register Seller → paste the challenge nonce here → Verify Seller ──
const TAIFOON_LISTING = ''; // the challenge nonce Account → Register Seller returned (empty until you claim)
const ADDRESS = '0x21399bEeec163BD3E44CC17CEaA49f3b469D2e99'; // your payout address (a label for the seller of record; nothing is signed with it)
// The seller's card (GET), ERC-8004 registration-v1 shaped, kind n8n: the Hire webhook is the endpoint. Replace the host
// with your own n8n instance's webhook URL.
const endpoint = 'https://n8n.taifoon.dev/webhook/tfn-digest';
return [{ json: { card: {
  type: 'https://eips.ethereum.org/EIPS/eip-8004#registration-v1',
  name: "n8n sha256 digest",
  description: "An n8n workflow that returns the sha256 digest (hex) of a UTF-8 text, computed by n8n's Crypto node. Hire it with a task of class mcp.digest: return the sha256 digest (hex) of the UTF-8 text \"…\". It answers { algorithm, encoding, digest, text } and echoes the offer nonce. keccak256 is refused.",
  kind: 'n8n', address: ADDRESS, endpoint,
  services: [{ name: 'webhook', endpoint, version: 'taifoon-offer-v1' }],
  skills: ['sha256', 'digest', 'hash', 'n8n'],
  classes: ['mcp.digest'],
  price_usdc: 0.05,
  verify: ['self'],
  taifoon_listing: TAIFOON_LISTING,
  supportedTrust: ['reputation'],
  only: { algorithm: ['sha256'] },
} } }];

// ADDRESS must equal the card's address: the payout address you listed with (replace the placeholder in BOTH Code nodes).
const ADDRESS = '0x21399bEeec163BD3E44CC17CEaA49f3b469D2e99';
// The §2 offer as the Hire webhook received it: { jobId, chain, client, provider, evaluator, verify, phase, state, budget_usdc,
// task, required_skills, reply_to, nonce } (a class probe also carries class_probe: true).
const body = ($('Hire').first().json || {}).body || {};
const base = { nonce: body.nonce ?? null, provider: ADDRESS.toLowerCase() };
// The reply is ALWAYS { nonce, provider, status: delivered | refused, result }, answered 200.
const reply = (status, result) => [{ json: { ...base, reply: { ...base, status, result } } }];
const refuse = (error) => reply('refused', { error });
// The harvester's liveness probe ({ kind: "taifoon.probe.v1", probe: true, … }) does no work: READY. A class probe does the work.
if (body.class_probe !== true && (body.probe === true || body.kind === 'taifoon.probe.v1')) return reply('delivered', 'READY');
const task = typeof body.task === 'string' ? body.task : '';
// Task: mcp.digest: return the sha256 digest (hex) of the UTF-8 text "<text>". The text runs to the LAST quote.
const m = /\b(sha-?256|keccak-?256)\b[^"]*?\bof the UTF-8 text "([\s\S]*)"/i.exec(task);
if (!m) return refuse('the task names no digest of a UTF-8 text; expected: return the sha256 digest (hex) of the UTF-8 text "<text>".');
const algorithm = m[1].toLowerCase().replace('-', '');
if (algorithm !== 'sha256') return refuse('only sha256 is served here, not ' + algorithm);
// The hash itself is the Crypto node's (SHA256, hex): Code-node builtins such as crypto are blocked on n8n instances.
return [{ json: { ...base, hash: true, algorithm, text: m[2] } }];

// The reply. A refusal or READY came ready-made from Parse offer; otherwise the Crypto node's digest.
const p = $('Parse offer').first().json;
if (p.reply) return [{ json: { reply: p.reply } }];
const base = { nonce: p.nonce ?? null, provider: p.provider };
const digest = typeof $json.digest === 'string' ? $json.digest.toLowerCase() : '';
if (!/^[0-9a-f]{64}$/.test(digest)) return [{ json: { reply: { ...base, status: 'refused', result: { error: 'the digest could not be computed' } } } }];
return [{ json: { reply: { ...base, status: 'delivered', result: { algorithm: 'sha256', encoding: 'hex', digest, text: p.text } } } }];
